import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import './ProductList.css';

function ProductList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const response = await axios.get('/api/products');
        setProducts(response.data);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching products:', error);
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  if (loading) return <div className="loading">Loading products...</div>;

  return (
    <div className="product-list">
      <h1>ROBLOX ITEMS FOR SALE</h1>
      {products.length === 0 ? (
        <p>No products available. Please add products through the admin panel.</p>
      ) : (
        <div className="products-grid">
          {products.map(product => (
            <Link key={product._id} to={`/product/${product._id}`} className="product-card">
              <div className="product-image">
                {product.image ? (
                  <img src={product.image} alt={product.name} />
                ) : (
                  <div className="placeholder">No Image</div>
                )}
              </div>
              <div className="product-info">
                <h3>{product.name}</h3>
                <p className="category">{product.category || 'General'}</p>
                <p className="price">${product.price}</p>
                <p className="stock">
                  {product.inStock ? 'In Stock' : 'Out of Stock'}
                </p>
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

export default ProductList;
